-- 0092_user_api_key.up.sql adds user-scoped long-lived API keys. A key is
-- an alternative credential for an existing app_user, not a machine identity:
-- empty scopes inherit the owner's live role permissions, while an explicit
-- scope array is a validated subset of the owner's current permission points.
--
-- Only a non-secret lookup prefix and an argon2id PHC hash are stored. The
-- full key is generated by NL and returned exactly once at creation and
-- rotation. Revocation flips a boolean and retains the row for audit history;
-- hard deletion removes the row while audit events continue to name the key
-- id and public prefix.
CREATE TABLE api_key (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    tenant_id    UUID NOT NULL REFERENCES tenant(id) ON DELETE CASCADE,
    user_id      UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,
    name         TEXT NOT NULL,
    key_prefix   TEXT NOT NULL,
    key_hash     TEXT NOT NULL,
    scopes       TEXT[],
    expires_at   TIMESTAMPTZ,
    revoked      BOOLEAN NOT NULL DEFAULT FALSE,
    last_used_at TIMESTAMPTZ,
    created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
    created_by   UUID NOT NULL REFERENCES app_user(id) ON DELETE CASCADE,

    CONSTRAINT api_key_name_chk CHECK (char_length(name) BETWEEN 1 AND 200)
);

CREATE UNIQUE INDEX api_key_key_prefix_idx ON api_key (key_prefix);
CREATE INDEX api_key_tenant_revoked_idx ON api_key (tenant_id, revoked);
